import{_ as a,o,c as e,ag as r}from"./chunks/framework.B5ULsuav.js";const c=JSON.parse('{"title":"如何处理人际关系","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-人际关系.md","filePath":"20-专题研究/topic-人际关系.md","lastUpdated":1778155802000}'),i={name:"20-专题研究/topic-人际关系.md"};function l(h,t,d,u,s,n){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="如何处理人际关系" tabindex="-1">如何处理人际关系 <a class="header-anchor" href="#如何处理人际关系" aria-label="Permalink to &quot;如何处理人际关系&quot;">​</a></h1><blockquote><p>专题分析：人际关系中的修行智慧 组合模型：圆融中和 + 对境不住 + 历境炼心</p></blockquote><hr><h2 id="一、核心原则" tabindex="-1">一、核心原则 <a class="header-anchor" href="#一、核心原则" aria-label="Permalink to &quot;一、核心原则&quot;">​</a></h2><blockquote><p><strong>&quot;家庭是道场，工作单位是道场，社会是道场。怎么去对待家庭？怎么去对待社会？就在日常生活中。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经1分-修行在生活中">金刚经1分-修行在生活中</a></p><blockquote><p><strong>&quot;我们总结的经验就是用道理和良心和人家对论。评价一件事情都是用道理和良心，只要守住这两条，永远立于不败之地。&quot;</strong></p></blockquote><p>— 修行入世（20090112b）</p><hr><h2 id="二、三种核心关系的修行" tabindex="-1">二、三种核心关系的修行 <a class="header-anchor" href="#二、三种核心关系的修行" aria-label="Permalink to &quot;二、三种核心关系的修行&quot;">​</a></h2><h3 id="_1-与家人的关系" tabindex="-1">1. 与家人的关系 <a class="header-anchor" href="#_1-与家人的关系" aria-label="Permalink to &quot;1. 与家人的关系&quot;">​</a></h3><blockquote><p><strong>&quot;家庭里面最重要还是我们男人。如果妻子不开心，你拉拉手摇摇肩膀都可以。两个人都是硬邦邦的，永远摆不平的。&quot;</strong></p></blockquote><p>— 修行入世（20090112b）</p><h3 id="_2-与同事的关系" tabindex="-1">2. 与同事的关系 <a class="header-anchor" href="#_2-与同事的关系" aria-label="Permalink to &quot;2. 与同事的关系&quot;">​</a></h3><blockquote><p><strong>&quot;了解就多帮助，不了解就少帮助，这是最客观的。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经4分-布施的分寸">金刚经4分-布施的分寸</a></p><p>能帮就帮一份。不抢功、不甩锅。</p><h3 id="_3-与不喜欢的人的关系" tabindex="-1">3. 与不喜欢的人的关系 <a class="header-anchor" href="#_3-与不喜欢的人的关系" aria-label="Permalink to &quot;3. 与不喜欢的人的关系&quot;">​</a></h3><blockquote><p><strong>&quot;功夫更深了你要想象和你的仇人在一起修炼，从恨他修到原谅他甚至是同情他。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/答疑2014-顺逆皆修与冤亲平等">答疑2014-顺逆皆修与冤亲平等</a></p><p>这才是真正的历境炼心——面对最不想面对的人，保持平常心。</p><hr><h2 id="三、人际关系三原则" tabindex="-1">三、人际关系三原则 <a class="header-anchor" href="#三、人际关系三原则" aria-label="Permalink to &quot;三、人际关系三原则&quot;">​</a></h2><h3 id="原则一-换位思维" tabindex="-1">原则一：换位思维 <a class="header-anchor" href="#原则一-换位思维" aria-label="Permalink to &quot;原则一：换位思维&quot;">​</a></h3><blockquote><p><strong>&quot;整体观定善恶——在任何一个时空点上，还是有是非对错的标准的。跳出局部，看全局。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-整体观是非对错">金刚经7分-整体观是非对错</a></p><p>与人发生矛盾时，先站到对方立场想一想。</p><h3 id="原则二-不执评价" tabindex="-1">原则二：不执评价 <a class="header-anchor" href="#原则二-不执评价" aria-label="Permalink to &quot;原则二：不执评价&quot;">​</a></h3><blockquote><p><strong>&quot;若菩萨有我相、人相、众生相、寿者相，即非菩萨。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经3分-四相与无我">金刚经3分-四相与无我</a></p><p>太在意别人对你的评价，是因为有&quot;我相&quot;。放下这个念头，人际关系轻松大半。</p><h3 id="原则三-随喜" tabindex="-1">原则三：随喜 <a class="header-anchor" href="#原则三-随喜" aria-label="Permalink to &quot;原则三：随喜&quot;">​</a></h3><blockquote><p><strong>&quot;随喜是众善奉行的第一步。看到别人做好事，心生欢喜。&quot;</strong></p></blockquote><p>— <a href="/liaokongjushi-wisdom/60-原文段落/金刚经11分-随喜即众善">金刚经11分-随喜即众善</a></p><p>看到同事做得好，不是嫉妒而是随喜；看到朋友成功，不是羡慕而是祝福。</p><hr><h2 id="四、具体场景对治" tabindex="-1">四、具体场景对治 <a class="header-anchor" href="#四、具体场景对治" aria-label="Permalink to &quot;四、具体场景对治&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>原文依据</th></tr></thead><tbody><tr><td>被人误解</td><td>&quot;不平静时问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot; — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></td></tr><tr><td>被人背叛</td><td>不结怨，保持距离。&quot;过去心不可得&quot; — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></td></tr><tr><td>被人批评</td><td>客观分析有没有道理，有则改之无则加勉</td></tr><tr><td>帮助人不被感激</td><td>&quot;了解就多帮助，不了解就少帮助&quot; — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经4分-布施的分寸">金刚经4分-布施的分寸</a></td></tr></tbody></table><hr><h2 id="五、常见误解" tabindex="-1">五、常见误解 <a class="header-anchor" href="#五、常见误解" aria-label="Permalink to &quot;五、常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th><th>原文依据</th></tr></thead><tbody><tr><td>修行人要和所有人搞好关系</td><td>随缘——&quot;有缘即住无缘去&quot;，不是讨好所有人</td><td>答疑精选</td></tr><tr><td>忍辱就是被人欺负也不吭声</td><td>忍辱是看破放下，不是憋着</td><td><a href="/liaokongjushi-wisdom/60-原文段落/答疑2014-顺逆皆修与冤亲平等">答疑2014-顺逆皆修与冤亲平等</a></td></tr><tr><td>不分别就是不分善恶</td><td>无分别是无私心分别，不是不辨是非</td><td><a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></td></tr></tbody></table><hr><h2 id="六、推荐模型" tabindex="-1">六、推荐模型 <a class="header-anchor" href="#六、推荐模型" aria-label="Permalink to &quot;六、推荐模型&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-圆融中和">圆融中和</a> — 整体观处世，换位思维</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-对境不住">对境不住</a> — 不被他人的评价带跑</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-历境炼心">历境炼心</a> — 在人际关系中磨炼心性</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-自然务实">自然务实</a> — 做该做的事，说该说的话</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-处世">dict-处世</a> — 处世即待人接物的修行</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-恕">dict-恕</a> — 己所不欲勿施于人</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-敬">dict-敬</a> — 恭敬心是人际关系的基础</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-07（全部原话添加原文段落链接，删除无法验证的引文，新增常见误解表，新增概念链接） 来源：修行入世（20090112b）、金刚经、答疑专辑</p></blockquote>',48)])])}const p=a(i,[["render",l]]);export{c as __pageData,p as default};
